# Smilei namelist generated by scripts/lwfa/ionization.jl from case "ionization-3d-wide" (plasma, seed 4).
# Do not edit; regenerate from the case file. Units: Smilei normalized, reference frequency = ω₀ (A1).
import math
import numpy as np

Main(
    geometry = "3Dcartesian",
    interpolation_order = 2,
    cell_length = [0.19634954084936207, 0.7853981633974483, 0.7853981633974483],
    number_of_cells = [448, 192, 192],
    timestep = 0.175864116302102,
    simulation_time = 299.76038623693285,
    number_of_patches = [32, 4, 4],
    EM_boundary_conditions = [["silver-muller"], ["silver-muller"], ["silver-muller"]],
    solve_poisson = False,
    reference_angular_frequency_SI = 2.3545644591360665e15,
    random_seed = 4,
    print_every = 200,
)

MovingWindow(time_start = 108.0, velocity_x = 1.0)

LaserGaussian3D(
    box_side = "xmin",
    a0 = 1.910860825850333,
    omega = 1.0,
    focus = [80.39269908169872, 75.39822368615503, 75.39822368615503],
    waist = 9.9498743710662,
    polarization_phi = 0.0,
    time_envelope = tgaussian(start = 0.0, duration = 114.20114290053988, fwhm = 9.990655333892372, center = 57.10057145026994),
    phase_offset = 5.849465022161006,
)

DiagScalar(every = [0, 1704, 142], precision = 12)

DiagFields(
    every = [0, 1704, 142],
    fields = ["Ex", "Ey"],
    subgrid = np.s_[:, 95:99, 95:99],
    datatype = "double",
)

def plasma_density(x, y, z):
    s = np.clip((x - 64.0) / 40.0, 0.0, 1.0)
    return 0.072 * np.sin(0.5 * math.pi * s)**2

def rise(s):
    return np.sin(0.5 * math.pi * np.clip(s / 4.0, 0.0, 1.0))**2

# The dopant's DopantSection along x on the rows around the axis. The rows are those whose centre
# lies inside the band; Smilei evaluates the profile at each particle's place, which puts a
# particle near a band edge on the side of its own place (the band's edges are on cell faces).
def dopant_density(x, y, z):
    return 0.00072 * rise(x - 108.0) * (1.0 - rise(x - 132.0)) * (np.abs(y - 75.39822368615503) < 14.137166941154069) * (np.abs(z - 75.39822368615503) < 14.137166941154069)

Species(
    name = "electron",
    position_initialization = "regular",
    regular_number = [1, 1, 1],
    momentum_initialization = "cold",
    particles_per_cell = 1,
    mass = 1.0, charge = -1.0,
    number_density = plasma_density,
    boundary_conditions = [["remove", "remove"], ["remove", "remove"], ["remove", "remove"]],
)

Species(
    name = "born",
    position_initialization = "regular",
    momentum_initialization = "cold",
    particles_per_cell = 0,
    mass = 1.0, charge = -1.0,
    number_density = 0.0,
    boundary_conditions = [["remove", "remove"], ["remove", "remove"], ["remove", "remove"]],
)

Species(
    name = "nitrogen",
    position_initialization = "regular",
    regular_number = [4, 4, 4],
    momentum_initialization = "cold",
    particles_per_cell = 64,
    atomic_number = 7,
    charge = 5.0,
    mass = 25706.13742802,
    number_density = dopant_density,
    time_frozen = 1.0e9,
    ionization_model = "tunnel",
    ionization_electrons = "born",
    boundary_conditions = [["remove", "remove"], ["remove", "remove"], ["remove", "remove"]],
)

# 0: the nitrogen's weight per charge state
DiagParticleBinning(deposited_quantity = "weight", every = [0, 1704, 142], species = ["nitrogen"],
                    axes = [["charge", 4.5, 7.5, 3]])

# 1, 2: born over (window x, u_x), the weight and weight·(γ − 1); 3: its spectrum ahead of fade[1]
DiagParticleBinning(deposited_quantity = "weight", every = [0, 1704, 142], species = ["born"],
                    axes = [["moving_x", 0.0, 87.96459430051421, 448], ["px", -10.0, 70.0, 320]])
DiagParticleBinning(deposited_quantity = "weight_ekin", every = [0, 1704, 142], species = ["born"],
                    axes = [["moving_x", 0.0, 87.96459430051421, 448], ["px", -10.0, 70.0, 320]])
DiagParticleBinning(deposited_quantity = "weight", every = [0, 1704, 142], species = ["born"],
                    axes = [["moving_x", 12.0, 87.96459430051421, 1], ["ekin", 0.0, 40.0, 200]])

# 4, 5: electron over (window x, u_x), the weight and weight·(γ − 1); 6: its spectrum ahead of fade[1]
DiagParticleBinning(deposited_quantity = "weight", every = [0, 1704, 142], species = ["electron"],
                    axes = [["moving_x", 0.0, 87.96459430051421, 448], ["px", -10.0, 70.0, 320]])
DiagParticleBinning(deposited_quantity = "weight_ekin", every = [0, 1704, 142], species = ["electron"],
                    axes = [["moving_x", 0.0, 87.96459430051421, 448], ["px", -10.0, 70.0, 320]])
DiagParticleBinning(deposited_quantity = "weight", every = [0, 1704, 142], species = ["electron"],
                    axes = [["moving_x", 12.0, 87.96459430051421, 1], ["ekin", 0.0, 40.0, 200]])

DiagTrackParticles(species = "born", every = [1704, 1704, 1], attributes = ["x", "px", "py", "pz", "w"])
